-- ES/DE/FR translations for all 5 Germany milestones.

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-xrechnung-b2g', 'es', 'XRechnung obligatorio para las autoridades públicas federales (B2G)', 'Toda factura enviada a un ministerio federal, autoridad estatal u organismo municipal alemán dentro del alcance debe cumplir con XRechnung o un formato equivalente conforme a EN 16931 — años antes de cualquier obligación B2B.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-xrechnung-b2g', 'de', 'XRechnung für Bundesbehörden (B2G) verpflichtend', 'Jede Rechnung, die an ein deutsches Bundesministerium, eine Landesbehörde oder eine im Anwendungsbereich liegende kommunale Stelle gesendet wird, muss XRechnung oder einem gleichwertigen EN-16931-konformen Format entsprechen — Jahre vor jeder B2B-Verpflichtung.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-xrechnung-b2g', 'fr', 'XRechnung obligatoire pour les autorités publiques fédérales (B2G)', 'Chaque facture envoyée à un ministère fédéral allemand, une autorité d''État ou un organisme municipal relevant du champ d''application doit être conforme à XRechnung ou à un format équivalent conforme à l''EN 16931 — des années avant toute obligation B2B.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-wachstumschancengesetz', 'es', 'La Wachstumschancengesetz (Ley de Oportunidades de Crecimiento) supera el Bundesrat', 'La ley que establece el mandato de facturación electrónica B2B de Alemania supera su último obstáculo legislativo, fijando el calendario por fases de 2025-2028.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-wachstumschancengesetz', 'de', 'Das Wachstumschancengesetz passiert den Bundesrat', 'Das Gesetz, das Deutschlands B2B-E-Invoicing-Vorgabe begründet, nimmt seine letzte legislative Hürde und legt den gestuften Zeitplan 2025-2028 fest.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-wachstumschancengesetz', 'fr', 'La Wachstumschancengesetz (loi sur les opportunités de croissance) franchit le Bundesrat', 'La loi établissant l''obligation de facturation électronique B2B de l''Allemagne franchit son dernier obstacle législatif, fixant le calendrier par phases 2025-2028.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-receive', 'es', 'Recepción obligatoria de facturas electrónicas estructuradas', 'Todas las empresas alemanas, independientemente de su tamaño, deben poder recibir facturas electrónicas estructuradas conformes con EN 16931 (XRechnung o ZUGFeRD) para transacciones B2B nacionales.', '["Confirme que su proceso de cuentas a pagar puede aceptar XML de XRechnung o PDFs híbridos de ZUGFeRD", "Una bandeja de entrada de correo electrónico capaz de recibir facturas estructuradas cumple con el mínimo actual"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-receive', 'de', 'Verpflichtender Empfang strukturierter E-Rechnungen', 'Alle deutschen Unternehmen, unabhängig von ihrer Größe, müssen in der Lage sein, EN-16931-konforme strukturierte E-Rechnungen (XRechnung oder ZUGFeRD) für inländische B2B-Transaktionen zu empfangen.', '["Bestätigen Sie, dass Ihr Kreditorenprozess XRechnung-XML oder ZUGFeRD-Hybrid-PDFs akzeptieren kann", "Ein E-Mail-Postfach, das strukturierte Rechnungen empfangen kann, erfüllt die derzeitige Mindestanforderung"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-receive', 'fr', 'Réception obligatoire des factures électroniques structurées', 'Toutes les entreprises allemandes, quelle que soit leur taille, doivent pouvoir recevoir des factures électroniques structurées conformes à l''EN 16931 (XRechnung ou ZUGFeRD) pour les transactions B2B domestiques.', '["Confirmez que votre processus de comptes fournisseurs peut accepter le XML XRechnung ou les PDF hybrides ZUGFeRD", "Une boîte e-mail capable de recevoir des factures structurées répond au minimum actuel"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-issue-large', 'es', 'Mandato de emisión — empresas con facturación superior a 800.000 €', 'Las empresas con una facturación del ejercicio anterior superior a 800.000 € deben emitir facturas electrónicas estructuradas para transacciones B2B nacionales; las facturas solo en PDF ya no son válidas para este grupo.', '["Confirme que su ERP puede generar salida en XRechnung o ZUGFeRD 2.1+", "Los acuerdos EDI existentes deben cumplir con EN 16931 o realizar la transición antes de finales de 2027"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-issue-large', 'de', 'Ausstellungspflicht — Unternehmen mit über 800.000 € Umsatz', 'Unternehmen mit einem Vorjahresumsatz über 800.000 € müssen strukturierte E-Rechnungen für inländische B2B-Transaktionen ausstellen; reine PDF-Rechnungen genügen für diese Gruppe nicht mehr.', '["Bestätigen Sie, dass Ihr ERP XRechnung- oder ZUGFeRD-2.1+-Ausgaben erzeugen kann", "Bestehende EDI-Vereinbarungen müssen bis Ende 2027 EN-16931-konform werden oder umgestellt werden"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-issue-large', 'fr', 'Obligation d''émission — entreprises dépassant 800 000 € de chiffre d''affaires', 'Les entreprises dont le chiffre d''affaires de l''exercice précédent dépasse 800 000 € doivent émettre des factures électroniques structurées pour les transactions B2B domestiques ; les factures uniquement en PDF ne sont plus valables pour ce groupe.', '["Confirmez que votre ERP peut générer une sortie XRechnung ou ZUGFeRD 2.1+", "Les accords EDI existants doivent devenir conformes à l''EN 16931 ou faire l''objet d''une transition avant fin 2027"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-issue-all', 'es', 'Mandato de emisión — todas las empresas B2B nacionales', 'La obligación de emisión se extiende a todas las empresas B2B nacionales independientemente de su facturación, completando la implementación por fases de Alemania bajo la Ley de Oportunidades de Crecimiento.', '["Complete la implementación en cualquier flujo de facturación B2B nacional restante", "No se aplicarán más disposiciones transitorias después de esta fecha"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-issue-all', 'de', 'Ausstellungspflicht — alle inländischen B2B-Unternehmen', 'Die Ausstellungspflicht erstreckt sich auf jedes inländische B2B-Unternehmen unabhängig vom Umsatz und schließt damit Deutschlands gestufte Einführung im Rahmen des Wachstumschancengesetzes ab.', '["Schließen Sie den Rollout für alle verbleibenden inländischen B2B-Rechnungsabläufe ab", "Nach diesem Datum gelten keine weiteren Übergangsregelungen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('de-issue-all', 'fr', 'Obligation d''émission — toutes les entreprises B2B domestiques', 'L''obligation d''émission s''étend à toute entreprise B2B domestique quel que soit son chiffre d''affaires, achevant le déploiement par phases de l''Allemagne dans le cadre de la loi sur les opportunités de croissance.', '["Achevez le déploiement pour tous les flux de facturation B2B domestiques restants", "Aucune disposition transitoire supplémentaire ne s''appliquera après cette date"]');
